import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem83 preserva identidade operação e idempotência sem decidir marca cor ou compatibilidade',()=>{for(const [id,titulo] of [['hVTGYQmARQt2fyDqPZDa','Sapatênis Microfibra Atanado Pinhão Navy Pegada'],['iFRhxwa7Jugs5n2BSQJD','Kit 8 Latas Refil Nautika Ntk 227g Camping Maçarico Fogareiro Fogão Recarga Gás Acampamento Portátil Cozinha Flambar Cozinhar Vivara Laranja-claro Kit 8 Latas Refil Nautika Ntk 22'],['IIBNXuN1JmBc0Ol6iO6O','Lixeira Inteligente 16l Sensor Automático Tampa Touch Casa']]){const p={id,titulo,preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.deepEqual(correctProductData(x),x);assert.equal(correctProductData({...p,titulo:'Outro produto',comentario:'manter'}).comentario,'manter');assert.doesNotMatch(x.pros,/compatibilidade universal|couro natural|impermeável|recarregável/i);assert.doesNotMatch(x.comentario,/\b\d+:\d+\b|\d+\s*%\s*(butano|propano)/i);}});
